// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2016, "4-5", [{"author":"Л. Фёдорова","question":"Как не здороваются?","choices":["<em>С добрым утром!</em>","<em>Доброе утро!</em>","<em>Добрый день!</em>","<em>Добрый вечер!</em>","<em>Добрая ночь!</em>"],"key":"Д","review":["Слова при встрече","Представь встречу утром, днём и вечером. Утром подойдут «С добрым утром!» и «Доброе утро!», днём — «Добрый день!», вечером — «Добрый вечер!».","Ближайшее знакомое выражение к «Добрая ночь!» — «Доброй ночи!». В обычной речи это пожелание на прощание или перед сном, поэтому вариант «Добрая ночь!» не подходит для приветствия."]},{"author":"М. Рубинштейн","question":"Одно из этих слов ― довольно распространённая русская фамилия. Какое?","choices":["<em>Отечество</em>","<em>Родина</em>","<em>Страна</em>","<em>Государство</em>","<em>Отчизна</em>."],"key":"Б","review":["Слово и фамилия","В списке даны названия страны и родной земли. Попробуй поставить каждое после женского имени, как фамилию.","«Родина» действительно встречается как женская форма фамилии «Родин». Сравни «Иван Родин» и «Анна Родина»."]},{"author":"Е. Бикмаев","question":"В каком словосочетании глагол <em>поставить</em> может означать не то, что в остальных?","choices":["<em>поставить чашку</em>","<em>поставить тарелку</em>","<em>поставить бокал</em>","<em>поставить чайник</em>","<em>поставить блюдо.</em>"],"key":"Г","review":["Глагол «поставить»","Представь, что ставишь чашку, тарелку, бокал или блюдо на стол. Во всех этих примерах действие означает, что предмет помещают на поверхность.","Просьба «Поставь чайник» часто значит «Начни греть в нём воду». Это дополнительное значение есть только у варианта с чайником."]},{"author":"О. Кузнецова","question":"Название какого из этих грибов не связано с названием животного?","choices":["<em>свинушка</em>","<em>боровик</em>","<em>лисичка</em>","<em>козлёнок</em>","все эти названия связаны с названиями животных."],"key":"Б","review":["Откуда имена грибов","Найди названия животных, которые слышны в словах. «Свинушка» связана со свиньёй, «лисичка» — с лисой, а козлёнком зовут ещё и детёныша козы.","«Боровик» связан со словом «бор», то есть с хвойным лесом. Название указывает на место, где можно найти гриб."]},{"author":"И. Иткин","question":"Какой по счёту месяц начинается с той же буквы, что время года, к которому он относится?","choices":["седьмой","восьмой","девятый","десятый","одиннадцатый."],"key":"Г","review":["Месяц и время года","Назови месяцы по номерам и распредели их по временам года. Седьмой и восьмой месяцы — июль и август, то есть лето. Девятый, десятый и одиннадцатый — сентябрь, октябрь и ноябрь, то есть осень.","Среди названий летних месяцев здесь нет слова на «л», а среди осенних на «о» начинается октябрь. Это десятый месяц."]},{"author":"Б. Иомдин","question":"<em>— Всё бы ничего, но вот Герцогиня, Герцогиня! Она придёт в ярость,</em> <em>если я опоздаю. Она именно туда и придёт!</em> Какое слово делает последнюю фразу Кролика из «Алисы в стране чудес» необычной?","choices":["<em>Она</em>","<em>именно</em>","<em>туда</em>","<em>и</em>","<em>придёт</em>."],"key":"В","review":["Куда собралась Герцогиня","Замени выражение «придёт в ярость» словом «разозлится». Так видно, что Кролик сначала говорит о чувстве Герцогини.","Слово «туда» отвечает на вопрос «куда?» и обычно указывает на место. Кролик шутливо говорит о ярости так, словно туда можно прийти."]},{"author":"Б. Иомдин","question":"<em>Подлежащее</em>, <em>глагол</em>, <em>прилагательное</em>, <em>предлог</em>, <em>существительное</em>.\nКакое слово, скорее всего, попало в этот список по ошибке?","choices":["<em>подлежащее</em>","<em>глагол</em>","<em>прилагательное</em>","<em>предлог</em>","<em>существительное</em>."],"key":"А","review":["Термины на уроке","Распредели термины по тому, что они называют. Глагол, прилагательное, предлог и существительное — части речи, то есть группы слов.","Подлежащее — член предложения. Например, в «Снег тает» слово «снег» относится к существительным, а в этом предложении служит подлежащим."]},{"author":"С. Переверзева","question":"На старом пузырьке Алиса увидела полустёршуюся надпись: «4 таблеток». «Наверное, — подумала она, — перед 4 должна была стоять ещё одна цифра, и это цифра …».","choices":["9","5","3","2","1."],"key":"Д","review":["Алисин пузырёк","Проверь обычные числа с последней цифрой 4. Говорят «двадцать четыре таблетки», «тридцать четыре таблетки», «пятьдесят четыре таблетки» и «девяносто четыре таблетки».","В числах от 11 до 14 нужна форма «таблеток». Из предложенных вариантов в этот ряд входит только 14, значит, перед четвёркой была единица."]},{"author":"Е. Добрушина","question":"Иногда похожие слова в близкородственных языках имеют противоположные значения: например, сербское слово <em>вредан</em> похоже на русское <em>вредный</em>, но означает ‘полезный’. Какое из пяти данных ниже польских слов обладает тем же свойством по отношению к русскому языку?","choices":["groza ‘ужас’","duma ‘гордость’","smutek ‘печаль’","umysł ‘ум’","uroda ‘красота’."],"key":"Д","review":["Похожие слова двух языков","Сравни польские слова с похожими русскими. «Groza» напоминает «гроза», «duma» — «дума», «smutek» — «смутный», «umysł» — «ум». Их переводы не противоположны смыслам этих русских слов.","Польское «uroda» означает «красота», хотя звучит похоже на русское «урод». Здесь близкое звучание сочетается с противоположными значениями."]},{"author":"С. Минлос","question":"В детской песенке на стихи Юнны Мориц есть такие строчки:\nПо роще калиновой,\nПо роще осиновой\nНа именины к щенку\nВ шляпе малиновой\nШёл ёжик резиновый\nС дырочкой в правом боку.\nКакие слова не связаны по смыслу со словом «шёл»?","choices":["<em>по роще</em>","<em>на именины</em>","<em>к щенку</em>","<em>с дырочкой</em>","все слова в (А)‒(Г) связаны по смыслу со словом <em>шёл</em>."],"key":"Г","review":["Резиновый ёжик в роще","Задай вопросы от «шёл». Шёл по чему? По роще. Зачем? На именины. К кому? К щенку.","«С дырочкой» отвечает на вопрос «какой ёжик?». Эти слова описывают самого ёжика и не объясняют, куда или как он шёл."]},{"author":"А. Пиперски","question":"Какой из этих предлогов <strong>не</strong> совпадает с глагольной приставкой?","choices":["<em>в</em>","<em>к</em>","<em>о</em>","<em>с</em>","<em>у</em>."],"key":"Б","review":["Предлоги и приставки","Найди глаголы с подходящим началом. Есть «вписать», «окружить», «сбежать» и «унести», в которых первые буквы — приставки «в-», «о-», «с-» и «у-».","Предлог «к» можно увидеть в сочетании «к дому», а глагольной приставки «к-» в современном русском языке нет. В «клеить», например, «к» входит в корень."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Тофсла и Вифсла, герои книги Туве Янссон «Шляпа волшебника» (перевод со шведского Л. Брауде), говорят по-особому. В какой фразе они образуют глагол не так, как в остальных?","choices":["<em>— Ты всёсла поняласла? — спросила Тофсла</em>.","<em>— Во всяком случаесла, они варятсла кофесла, — пробормотала</em> <em>Вифсла</em>.","<em>— Кто-то крадётсла! — прошептала Тофсла. — Тихо, как</em> <em>мышкасла!</em>","<em>— Он следитсла за нами, — прошептала Вифсла</em>.","<em>— Страхсла и ужассла! — объяснила Вифсла. — Запирайтесла дверисла</em> <em>от Морры!</em>"],"key":"В","review":["Речь Тофслы и Вифслы","Отними «сла» у четырёх глаголов. «Поняласла», «варятсла», «следитсла» и «запирайтесла» превращаются в «поняла», «варят», «следит» и «запирайте».","В реплике про мышку кто-то тихо подбирается к героям, то есть «крадётся». В «крадётсла» обычное «-ся» заменено на «-сла». Простое «крадёт» означало бы, что кто-то ворует."]},{"author":"К. Кноп","question":"Начальник сказал подчинённым: «Из-за таких, как вы, у нас в стране корабли идут под откос». А что на самом деле может идти под откос?","choices":["эскалатор","лифт","поезд","самолёт","начальник прав — корабль."],"key":"В","review":["Что идёт под откос","Откос — наклонная сторона насыпи. Например, у высокой железнодорожной насыпи земля по бокам спускается вниз.","Поезд может сойти с рельсов и покатиться вниз по этому склону. Отсюда выражение «поезд пошёл под откос»."]},{"author":"А. Панина","question":"Если некто <em>хорош собой</em>, это значит, что он … .","choices":["хороший","умный","добрый","красивый","честный."],"key":"Г","review":["Что значит «хорош собой»","Сравни фразы «Он хорошо поступил» и «Он хорош собой». В первой оценивают поступок, а во второй внешность человека.","Так можно сказать, например, о человеке с красивым лицом. «Хорош собой» значит «красивый»."]},{"author":"О. Подлесская","question":"Про какой знак препинания знаменитый писатель Владимир Набоков сказал, что «это следы на цыпочках ушедших слов»?","choices":["скобки","кавычки","двоеточие","многоточие","точка с запятой."],"key":"Г","review":["Следы ушедших слов","Представь, что фраза обрывается на полуслове или часть высказывания пропущена. В письменной речи такой пропуск можно специально обозначить знаком.","Три точки подряд образуют многоточие. Они помогают читателю заметить, что на месте знака могли быть ещё слова."]},{"author":"Л. Фёдорова","question":"В книге Джеймса Крюса «Тим Талер, или Проданный смех» мальчик Тим, сам того не подозревая, заключил договор с представителем нечистой силы. А каким именем тот подписался?","choices":["<em>Греч</em>","<em>Свеч</em>","<em>Трёч</em>","<em>Глюч</em>","<em>Флинч</em>."],"key":"В","review":["Подпись в договоре","Подумай, каким словом в сказках называют представителя нечистой силы. Варианты подсказывают слово «чёрт», потому что сочетание «рё» появляется в одном из имён.","Прочитай «чёрт» справа налево. Получится «трёч» — так и подписался персонаж."]},{"author":"С. Бурлак","question":"В какое слово <strong>нельзя</strong> вставить мягкий знак между подчёркнутыми буквами и получить новое слово?","choices":["про<u>шу</u>","гос<u>ти</u>","бо<u>же</u>","по<u>лё</u>т","во все слова можно"],"key":"А","review":["Мягкий знак в слове","Вставь «ь» на места, указанные подчёркиваниями. Получаются «гостьи», «божье» и «польёт». Такие слова есть, например, во фразах «две гостьи», «божье творение», «польёт цветы».","В «прошу» подчеркнуты «ш» и «у». Если вставить между ними знак, получится «прошьу». Такого слова нет, форму от «прошить» пишут «прошью»."]},{"author":"Е. Муравенко","question":"Если записать сначала второй слог слова <em>банка</em>, а потом первый, получится другое слово: <em>кабан</em>. Найдите ещё одно такое слово.","choices":["<em>лунка</em>","<em>пальто</em>","<em>марка</em>","<em>арфа</em>","<em>скала</em>."],"key":"Д","review":["Слоги меняются местами","Поменяй части в каждом варианте так же, как в паре «бан-ка — ка-бан». В первых четырёх выходят «калун», «топаль», «камар» и «фаар».","Из «ска-ла» выходит «ла-ска». Это слово можно употребить и о нежном прикосновении, и о небольшом хищном зверьке."]},{"author":"П. Аркадьев","question":"Какое слово <strong>не</strong> может быть существительным?","choices":["<em>светил</em>","<em>светила</em>","<em>светило</em>","<em>светили</em>","ни одно из слов (А)–(Г) не может быть существительным."],"key":"Г","review":["Формы слова «светило»","Проверь, где слово может называть предмет. Получаются «яркое светило», «яркие светила» и «несколько ярких светил».","«Светили» работает как глагол, например «Звёзды светили всю ночь». Среди данных форм существительного «светило» такой формы нет."]},{"author":"В. Антонюк","question":"В какой паре уменьшительные имена <strong>не</strong> могут быть формами одного и того же полного имени?","choices":["<em>Аня</em> и <em>Нюра</em>","<em>Саша</em> и <em>Шура</em>","<em>Дима</em> и <em>Митя</em>","<em>Люся</em> и <em>Мила</em>","в каждой паре уменьшительные имена могут быть формами одного полного имени."],"key":"Д","review":["Полные и короткие имена","Подбери полное имя к первым двум парам. Анну могут звать Аней или Нюрой, Александра — Сашей или Шурой.","Дима и Митя могут быть сокращениями имени Дмитрий, а Люся и Мила — имени Людмила. Значит, общее полное имя находится для каждой пары."]},{"author":"А. Сомин","question":"В Институте редких и исчезающих видов в Южной Каролине живёт лигр по кличке Вулкан. А кто его родители?","choices":["леопард Игренд и пума Лесси","тигр Лир и самка ягуара Грета","лев Артур и тигрица Айла","ягуар Симон и леопардица Джесси","лев Грей и пантера Лита."],"key":"В","review":["Семья лигра Вулкана","В названии «лигр» угадываются два больших зверя. Первая буква напоминает о льве, а «-игр» — конец слова «тигр». Найди в списке пару из этих животных.","У лигра отец — лев, а мать — тигрица. В списке это лев Артур и тигрица Айла."]},{"author":"И. Иткин и С. Переверзева","question":"Маленькому Лёве всего год, но он уже знает довольно много слов. Одни слова он как-то по-своему говорит (например, <em>живот</em>, <em>кукла</em>, <em>пуп</em>, <em>рука</em>, <em>сапоги</em>, <em>сок</em>), другие ― не говорит, а только показывает пальцем на соответствующий объект (например, <em>голова</em>, <em>ноздря</em>, <em>нос</em>, <em>ухо</em>, <em>язык</em>). В какие из этих двух групп попадают слова <em>бок</em>, <em>волосы</em>, <em>глаз</em>, <em>дом</em>, <em>печенье</em>?","choices":["<em>дом</em> и <em>печенье</em> ― говорит, <em>бок</em>, <em>волосы</em> и <em>глаз</em> ― только показывает","<em>бок</em>, <em>глаз</em> и <em>дом</em> ― говорит, <em>волосы</em> и <em>печенье</em> ― только показывает","<em>бок</em>, <em>дом</em> и <em>печенье</em> ― говорит, <em>волосы</em> и <em>глаз</em> ― только показывает","<em>печенье</em> ― говорит, <em>бок</em>, <em>волосы</em>, <em>глаз</em> и <em>дом</em> ― только показывает","<em>волосы</em> и <em>глаз</em> ― говорит, <em>бок</em>, <em>печенье</em> и <em>дом</em> ― только показывает."],"key":"В","review":["Слова маленького Лёвы","Сравни, что обозначают две группы слов. «Голова», «ноздря», «нос», «ухо» и «язык» относятся к голове. Лёва показывает их, а живот, пуп и рука расположены ниже, их названия он говорит.","Волосы и глаз тоже находятся на голове, поэтому Лёва их показывает. Бок расположен ниже, а дом и печенье, как кукла и сок, вовсе не части тела. Эти три слова он говорит."]},{"author":"С. Переверзева","question":"Урфин Джюс, персонаж сказок А. М. Волкова, любил, по его выражению, «схватить судьбу за рога». А кого обычно «берут за рога»?","choices":["козла","быка","барана","оленя","улитку."],"key":"Б","review":["Урфин и рога","Урфин хотел решительно управлять своей судьбой. Вспомни поговорку о том, как сразу взяться за трудное дело.","Она звучит «взять быка за рога». Урфин заменил быка на судьбу, чтобы выразить ту же решимость."]},{"author":"И. Иткин","question":"Какое из этих значений по-русски можно выразить одним словом?","choices":["‘посмотреть вперёд’","‘посмотреть назад’","‘посмотреть вверх’","‘посмотреть вниз’","‘посмотреть вдаль’."],"key":"Б","review":["В какую сторону посмотреть","Представь, что тебя окликнули со спины. Ты повернёшь голову и посмотришь, кто идёт за тобой.","Всё это действие можно назвать одним глаголом «оглянуться». Он передаёт направление «назад»."]},{"author":"А. Сомин","question":"Даны русские слова и их переводы на белорусский язык: <em>светлая ― светлая, свешивала ― звешвала, слева ― злева</em>, <em>снег ― снег</em>, <em>снимала ― знімала</em>. Перевод какого из этих русских слов будет начинаться в белорусском языке с буквы <em>с</em>?","choices":["<em>смешивалась</em>","<em>смирилась</em>","<em>сменялась</em>","<em>смягчалась</em>","<em>смеялась</em>."],"key":"Д","review":["Белорусские переводы","Сравни начало слов. В «светлая» и «снег» буква «с» входит в корень и сохраняется, а в «свешивала», «слева» и «снимала» приставка «с-» передаётся белорусской «з-».","В первых четырёх вариантах «с-» можно отделить от корня, как в парах «смешать — мешать» и «сменить — менять». В «смеялась» начальная «с» входит в корень, поэтому по-белорусски будет «смяялася»."]},{"author":"Е. Муравенко","question":"Мальчишки играли на берегу моря камешками и придумывали для каждого вида камешков свои названия. «Смотрите, как у меня много крело́в!» — воскликнул Даня. Миша огорчился: «А у меня только один крел». Яша поправил его: «Одна крела́». Владик возразил: «Да нет, одна крело́ва». Кто из ребят точно ошибся в образовании единственного числа нового слова?","choices":["только Миша","только Яша","только Владик","все, кроме Миши","все, кроме Владика."],"key":"Б","review":["Названия для камешков","Испытай две формы по знакомым образцам. Если есть «один крел», получится «много крело́в», как «стол — столо́в». Если есть «одна крело́ва», тоже можно получить «много крело́в», как «осно́ва — осно́в».","У формы «одна крела́» убирается окончание «-а», как в «сестра́ — сестёр», и окончания «-ов» не появляется. Поэтому именно Яшино предложение не согласуется с «много крело́в»."]},{"author":"Л. Фёдорова","question":"В какой паре слова <strong>не</strong> однокоренные?","choices":["<em>спрашивать ― справка</em>","<em>завешивать ― занавеска</em>","<em>замечать ― отметка</em>","<em>выбирать ― уборка</em>","во всех парах слова однокоренные."],"key":"А","review":["Пары родственных слов","Найди общие корни, даже если звуки в них меняются. «Завешивать» и «занавеска» связаны с тем, что вешают, «замечать» и «отметка» — с меткой, «выбирать» и «уборка» — с корнем «-бир-/-бер-/-бор-» глагола «брать».","В слове «спрашивать» корень тот же, что в «спросить». У «справки» другой корень, как в «справиться о чём-либо». Сходство смысла здесь не делает слова однокоренными."]},{"author":"И. Погодаев","question":"Андриан едет в московском метро. Он проехал станции: Южную, Чертановскую, Севастопольскую, Нахимовский проспект, Нагорную, Нагатинскую. «Как логично!»\n— воскликнул он, и в этот момент диктор объявил: «Осторожно, двери закрываются. Следующая станция — Тульская». «Ну вот, — подумал Андриан, — лучше бы это была не Тульская, а …».","choices":["Серпуховская","Чеховская","Тимирязевская","Менделеевская","Пражская."],"key":"Г","review":["Порядок станций метро","Сравни названия по алфавиту. Они идут в обратном порядке от «Ю» к «Ч», «С» и «Н». Три названия на «На» тоже идут так — «Нахимовский», «Нагорная», «Нагатинская».","После последней станции на «Н» подойдёт начальная буква, которая стоит раньше неё в алфавите. Только «Менделеевская» на «М» выполняет это условие."]},{"author":"Л. Фёдорова","question":"Однажды Гусак, Червяк, Барсук, Поросёнок и Бурундук поспорили, у кого самое простое имя. «Только в моём имени нет суффикса», ― сказал Бурундук. А на самом деле такое имя … .","choices":["и у Гусака","и у Червяка","и у Барсука","и у Поросёнка","только у Бурундука, он прав."],"key":"В","review":["Имена зверей на спор","Разбери имена. «Гусак» образован от «гусь», «червяк» — от «червь», «поросёнок» назван с помощью суффикса детёнышей «-ёнок».","Хотя «барсук» начинается так же, как «барс», это отдельное слово с корнем «барсук-». Оно, как и «бурундук», обходится без суффикса."]},{"author":"Б. Иомдин","question":"Озвучивая фильм, актёры читали вслух предложения:\n— Давай поешь бульончику, и все пройдет.\n— Когда поешь, становится немного теплей.\n— Поешь, полежишь и немного отойдешь.\n— Приедешь, поешь и еще позанимаешься.\n— Ветер, у костра не посидишь, не поешь.\nКакое предложение можно прочитать вслух двумя способами так, что от этого будет меняться смысл?","choices":["первое","второе","третье","четвёртое","пятое."],"key":"Б","review":["Как прочитать «поешь»","Различи «пое́шь» от «поесть» и «поёшь» от «петь». В первой реплике есть бульон, а в третьей, четвёртой и пятой говорят о действиях в будущем, например «приедешь» и «позанимаешься». Там подходит «пое́шь».","Во втором предложении потеплеть может и после еды, и от пения. Поэтому «Когда пое́шь, становится немного теплей» и «Когда поёшь, становится немного теплей» передают два разных смысла."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
